  }
 },
 {
  "qid": "q3",
  "question": "Is the epoch-3 trained belief for corrections before the claim at least 0.8 times the affirm anchor?",
  "labels": {
   "yes": "For corr_before and corr_top, the epoch-3 judged belief is at least 0.8 times the affirm anchor.",
   "no": "For corr_before and corr_top, the epoch-3 judged belief is below 0.8 times the affirm anchor."
  }
 }
]

